$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$failures = New-Object System.Collections.Generic.List[string]

function Fail([string]$message) { $failures.Add($message) }

# Files generated by the build/test toolchain are allowed to exist in a local
# checkout after readiness runs. They are not public source and must not be
# inspected as if they were authored files. This matcher intentionally accepts
# both Windows (\\) and Unix-style (/) separators.
function Test-IsAuditExcludedPath([string]$path) {
    return $path -match '[\\/](bin|obj|dist|artifacts|TestResults|\.git|\.vs|\.idea)[\\/]'
}

# Regression guards for the exclusion matcher. A successful readiness build on
# Windows creates src\\...\\bin and src\\...\\obj before this audit runs.
if (-not (Test-IsAuditExcludedPath 'C:\\repo\\src\\App\\bin\\Release\\App.dll')) {
    Fail 'Public-audit regression: Windows bin path was not excluded.'
}
if (-not (Test-IsAuditExcludedPath '/repo/src/App/obj/project.assets.json')) {
    Fail 'Public-audit regression: Unix-style obj path was not excluded.'
}
if (Test-IsAuditExcludedPath 'C:\\repo\\src\\App\\Services\\GitService.cs') {
    Fail 'Public-audit regression: authored source path was excluded.'
}

$required = @(
    'LICENSE', 'COMMERCIAL-LICENSING.md', 'README.md', 'SECURITY.md', 'CONTRIBUTING.md', 'CODE_OF_CONDUCT.md',
    '.editorconfig', 'global.json', 'docs\PRIVACY.md', 'docs\ARCHITECTURE.md', 'docs\TESTING.md',
    'docs\RELEASING.md', 'docs\BRANDING.md', 'docs\PUBLIC_READINESS_AUDIT_0.15.md',
    'src\NRS.Workbench.App\Assets\NRSWorkbench.ico', 'src\NRS.Workbench.App\Assets\NRSWorkbench.png'
)
foreach ($relative in $required) {
    if (-not (Test-Path (Join-Path $root $relative))) { Fail "Missing required public file: $relative" }
}

# Licensing regression guards. The public release is source-available under
# PolyForm Noncommercial 1.0.0, with commercial licensing reserved by Neo RS.
$licensePath = Join-Path $root 'LICENSE'
$readmePath = Join-Path $root 'README.md'
$aboutPath = Join-Path $root 'src\NRS.Workbench.App\AboutWindow.xaml'
if (Test-Path $licensePath) {
    $licenseText = Get-Content $licensePath -Raw
    if ($licenseText -notmatch 'PolyForm-Noncommercial-1\.0\.0') { Fail 'LICENSE is missing the PolyForm Noncommercial SPDX identifier.' }
    if ($licenseText -notmatch 'Required Notice:\s*Copyright 2026 Neo RS') { Fail 'LICENSE is missing the required Neo RS copyright notice.' }
    if ($licenseText -match '(?m)^MIT License\s*$') { Fail 'LICENSE unexpectedly reverted to MIT.' }
}
if (Test-Path $readmePath) {
    $readmeText = Get-Content $readmePath -Raw
    if ($readmeText -notmatch '(?i)source-available') { Fail 'README does not identify the project as source-available.' }
    if ($readmeText -notmatch 'PolyForm Noncommercial License 1\.0\.0') { Fail 'README does not state the PolyForm Noncommercial license.' }
}
if (Test-Path $aboutPath) {
    $aboutText = Get-Content $aboutPath -Raw
    if ($aboutText -match 'Text="MIT"') { Fail 'About window still exposes MIT as the active license.' }
    if ($aboutText -match 'Open source · Public Preview') { Fail 'About window still describes the project as open source.' }
    if ($aboutText -notmatch 'PolyForm Noncommercial 1\.0\.0') { Fail 'About window does not expose the PolyForm license.' }
}

# Build output may legitimately exist after the readiness build. Only fail when
# generated folders are actually tracked by Git.
if (Test-Path (Join-Path $root '.git')) {
    $tracked = @(& git -C $root ls-files 2>$null)
    foreach ($path in $tracked) {
        if ($path -match '(^|/)(bin|obj|dist|artifacts|TestResults)/') { Fail "Generated artifact is tracked by Git: $path" }
    }
}

$forbiddenFiles = Get-ChildItem $root -Recurse -Force -File | Where-Object {
    -not (Test-IsAuditExcludedPath $_.FullName) -and (
        $_.Name -in @('.credentials', '.credentials_rsaparams', 'settings.json') -or
        $_.Name -like '*.pfx' -or $_.Name -like '*.p12' -or $_.Name -like '*.key'
    )
}
foreach ($item in $forbiddenFiles) { Fail "Sensitive/local file present: $($item.FullName)" }

$textFiles = Get-ChildItem $root -Recurse -Force -File | Where-Object {
    -not (Test-IsAuditExcludedPath $_.FullName) -and
    $_.Extension -in @('.cs', '.xaml', '.csproj', '.props', '.ps1', '.cmd', '.json', '.yml', '.yaml')
}

$secretPatterns = @(
    'github_pat_[A-Za-z0-9_]{20,}',
    'gh[pousr]_[A-Za-z0-9]{20,}',
    '-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----'
)
foreach ($file in $textFiles) {
    $content = Get-Content $file.FullName -Raw -ErrorAction SilentlyContinue
    if ($null -eq $content) { continue }
    foreach ($pattern in $secretPatterns) {
        if ($content -match $pattern) { Fail "Possible secret in $($file.FullName): pattern $pattern" }
    }
}

$sourceFiles = Get-ChildItem (Join-Path $root 'src') -Recurse -Force -File | Where-Object {
    -not (Test-IsAuditExcludedPath $_.FullName)
}

# Match G:\ only when it starts a standalone Windows path token. A simple
# case-insensitive `G:\` check also matches regex source such as `Starting:\s*`
# because the final `g` in "Starting" is followed by `:\`.
$personalGDrivePattern = '(?i)(?<![A-Za-z0-9_])G:\\'
if ('@"\bStarting:\s*(?<name>.+?)\s*$"' -match $personalGDrivePattern) {
    Fail 'Public-audit regression: regex syntax was mistaken for a G: drive path.'
}
if (-not ('@"G:\Private\repo"' -match $personalGDrivePattern)) {
    Fail 'Public-audit regression: a real G: drive path was not detected.'
}

foreach ($file in $sourceFiles) {
    $content = Get-Content $file.FullName -Raw -ErrorAction SilentlyContinue
    if ($null -eq $content) { continue }
    if ($content -match '[A-Za-z]:\\Users\\[^\\\r\n]+') { Fail "Personal user path in source: $($file.FullName)" }
    if ($content -match $personalGDrivePattern) { Fail "Personal G: path in source: $($file.FullName)" }
    if ($content -match '(?i)Nfreakz') { Fail "Personal repository/account name hardcoded in source: $($file.FullName)" }
}

$xamlFiles = Get-ChildItem (Join-Path $root 'src') -Recurse -Force -Filter '*.xaml' -File | Where-Object {
    -not (Test-IsAuditExcludedPath $_.FullName)
}
foreach ($file in $xamlFiles) {
    $content = Get-Content $file.FullName -Raw
    if ($content -match 'LetterSpacing=') { Fail "Unsupported WPF LetterSpacing in $($file.FullName)" }
    if ($content -match 'LineHeight=') { Fail "Previously problematic LineHeight in $($file.FullName)" }
    try { [void][xml]$content }
    catch { Fail "Malformed XAML/XML in $($file.FullName): $($_.Exception.Message)" }
}

if ($failures.Count -gt 0) {
    Write-Host "PUBLIC AUDIT FAILED ($($failures.Count))" -ForegroundColor Red
    $failures | ForEach-Object { Write-Host " - $_" -ForegroundColor Red }
    exit 1
}

Write-Host 'PUBLIC AUDIT PASSED' -ForegroundColor Green
Write-Host "Checked $($textFiles.Count) source/config files and $($xamlFiles.Count) XAML files."
